// ─── File: src/main/java/com/bank/safepool/service/SafePoolFactory.java ───
package com.bank.safepool.service;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Exposes the DANGEROUS cached config and the SAFE bounded config side by side.
public class SafePoolFactory {
    private static final Logger log = Logger.getLogger(SafePoolFactory.class.getName());

    // DANGEROUS for long tasks: 0 core, MAX_VALUE max, SynchronousQueue → unbounded threads.
    public ExecutorService dangerousCachedPool() {
        log.warning("Creating cached pool — UNBOUNDED threads, unsafe for long tasks!");
        return Executors.newCachedThreadPool();
    }

    // SAFE: capped threads + bounded queue + back-pressure rejection policy.
    public ThreadPoolExecutor safeBoundedPool(int maxThreads, int queueCapacity) {
        log.info(() -> "Creating bounded pool max=" + maxThreads + " queue=" + queueCapacity);
        return new ThreadPoolExecutor(
                maxThreads, maxThreads,
                60L, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(queueCapacity),
                r -> {
                    Thread t = new Thread(r, "fraud-worker");
                    t.setDaemon(false);
                    return t;
                },
                new ThreadPoolExecutor.CallerRunsPolicy());   // overload → back-pressure
    }

    // SAFE for blocking IO inside CompletableFuture: a DEDICATED executor, NOT the common pool.
    public ExecutorService dedicatedIoExecutor(int size) {
        log.info(() -> "Creating dedicated IO executor size=" + size + " (keeps blocking off common pool)");
        return Executors.newFixedThreadPool(size);
    }
}
```

