package com.bank.safepool.service;

import java.util.concurrent.Callable;

// Simulates a long blocking fraud check (external scoring service call).
public class FraudCheckTask implements Callable<String> {
    private final String accountId;
    private final long durationMs;

    public FraudCheckTask(String accountId, long durationMs) {
        this.accountId = accountId;
        this.durationMs = durationMs;
    }

    @Override
    public String call() throws InterruptedException {
        Thread.sleep(durationMs);                 // long blocking work
        return "FRAUD-OK:" + accountId;
    }
}
