// ─── File: src/main/java/com/bank/safepool/service/SafePoolApplication.java ───
package com.bank.safepool.service;

import java.util.concurrent.*;
import java.util.logging.Logger;

// Runnable demo: the bounded pool caps threads; blocking IO uses a dedicated executor.
public class SafePoolApplication {
    private static final Logger log = Logger.getLogger(SafePoolApplication.class.getName());

    public static void main(String[] args) throws Exception {
        SafePoolFactory factory = new SafePoolFactory();

        // SAFE bounded pool: submit more work than capacity → back-pressure, no explosion.
        ThreadPoolExecutor safe = factory.safeBoundedPool(8, 50);
        for (int i = 0; i < 100; i++) {
            final String acct = (i % 2 == 0) ? "SAV2001" : "CUR3001";
            safe.submit(new FraudCheckTask(acct, 20));
        }
        log.info("Peak pool size stays bounded at max=8: " + safe.getLargestPoolSize());
        safe.shutdown();
        safe.awaitTermination(30, TimeUnit.SECONDS);

        // SAFE blocking IO with CompletableFuture on a DEDICATED executor (not common pool).
        ExecutorService io = factory.dedicatedIoExecutor(16);
        CompletableFuture<String> f = CompletableFuture.supplyAsync(
                () -> {
                    try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                    return "BALANCE:SAV2001=1000000";
                }, io);                              // explicit executor → stays off common pool
        log.info("Dedicated IO result: " + f.get());
        io.shutdown();
    }
}
```

