// ─── File: src/test/java/com/bank/safepool/service/SafePoolFactoryTest.java ───
package com.bank.safepool.service;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.assertThat;

class SafePoolFactoryTest {

    private final SafePoolFactory factory = new SafePoolFactory();

    @Test
    void boundedPool_neverExceedsMaxThreads() throws InterruptedException {
        ThreadPoolExecutor pool = factory.safeBoundedPool(8, 50);
        for (int i = 0; i < 200; i++) {
            pool.submit(new FraudCheckTask("SAV2001", 10));
        }
        pool.shutdown();
        pool.awaitTermination(30, TimeUnit.SECONDS);
        // Even with 200 long tasks, threads are capped at 8 — no explosion.
        assertThat(pool.getLargestPoolSize()).isLessThanOrEqualTo(8);
    }

    @Test
    void cachedPool_isUnboundedByDesign() {
        ThreadPoolExecutor cached = (ThreadPoolExecutor) factory.dangerousCachedPool();
        assertThat(cached.getMaximumPoolSize()).isEqualTo(Integer.MAX_VALUE);  // the danger
        assertThat(cached.getCorePoolSize()).isEqualTo(0);
        cached.shutdown();
    }

    @Test
    void dedicatedIoExecutor_runsOffCommonPool() throws Exception {
        ExecutorService io = factory.dedicatedIoExecutor(4);
        String threadName = CompletableFuture.supplyAsync(
                () -> Thread.currentThread().getName(), io).get();
        // Must NOT be a common-pool worker thread.
        assertThat(threadName).doesNotContain("ForkJoinPool.commonPool");
        io.shutdown();
    }

    @Test
    void boundedPool_appliesBackPressureNotRejectionCrash() throws InterruptedException {
        ThreadPoolExecutor pool = factory.safeBoundedPool(2, 2);
        // Submit far more than core+queue; CallerRunsPolicy makes the caller run it → no crash.
        for (int i = 0; i < 20; i++) pool.submit(new FraudCheckTask("CUR3001", 5));
        pool.shutdown();
        assertThat(pool.awaitTermination(30, TimeUnit.SECONDS)).isTrue();
    }
}
